import { useState } from "react";
import { SectionPage, Specimen } from "../kit.js";
import {
  DragDropProvider,
  DropZoneScope,
  moveItem,
  useDraggable,
  useDropZone,
} from "../../ui/drag-drop/index.js";

/** A zone and items built with the hooks, for elements a host already renders. */
function HookTray() {
  const [items, setItems] = useState(["Sample A", "Sample B", "Sample C"]);
  const zone = useDropZone({
    id: "tray",
    label: "Tray",
    sort: "horizontal",
    onDrop: (event) =>
      setItems((current) => moveItem(current, event.source.index ?? 0, event.target.index ?? 0)),
  });
  return (
    <div
      ref={zone.ref}
      className="fa-dnd-zone flex gap-2 rounded-[var(--radius-tile)] border border-[var(--line)] p-2"
      data-appearance="outline"
      aria-label="Tray"
    >
      <DropZoneScope zoneId="tray">
        {items.map((item) => (
          <HookItem key={item} label={item} />
        ))}
      </DropZoneScope>
    </div>
  );
}

function HookItem({ label }: { label: string }) {
  const item = useDraggable({ id: `hook-${label}`, label });
  return (
    <div
      ref={item.ref}
      {...item.handleProps}
      className="rounded-[var(--radius-chip)] bg-[var(--glass-fill-control)] px-3 py-1.5 text-sm"
      data-dragging={item.dragging ? "" : undefined}
    >
      {label}
    </div>
  );
}

export default function DragDropSection() {
  return (
    <SectionPage>
      <Specimen
        title="Hooks"
        description="useDropZone and useDraggable attach to elements you render; DropZoneScope puts the items inside in the zone. Add the fa-dnd-zone class and data-appearance for the standard states."
        layout="stack"
        specimenKey="drag-drop:default:6"
      >
        <DragDropProvider>
          <HookTray />
        </DragDropProvider>
      </Specimen>
    </SectionPage>
  );
}
